        - Constraints: ["!(!batch) || !(!(buf[0] == 'y' || buf[0] == 'Y'))", '!(!batch) || !(fgets(buf, sizeof(buf), stdin) == NULL)', '!(rrow != NULL)', "!(row[DB_name][0] == '\\0') || !(row[DB_name] == NULL)", '!(row[DB_serial] == NULL)', '!(row[DB_name] == NULL)', '!(!email_dn) || !(!X509_set_subject_name(ret, dn_subject))', '!(!email_dn) || !((dn_subject = X509_NAME_dup(subject)) == NULL)', '!(!copy_extensions(ret, req, ext_copy))', '!(ext_sect) || !(ext_sect) || !(!X509V3_EXT_add_nconf(lconf, &ext_ctx, ext_sect, ret))', '!(ext_sect) || !(extfile_conf != NULL) || !(!X509V3_EXT_add_nconf(extfile_conf, &ext_ctx, ext_sect, ret))', '!(selfsign) || !(!X509V3_set_issuer_pkey(&ext_ctx, pkey))', '!(!i)', '!(!X509_set_subject_name(ret, subject))', '!(enddate != NULL) || !(!ASN1_TIME_diff(&tdays, NULL, NULL, X509_get0_notAfter(ret)))', '!(!set_cert_times(ret, startdate, enddate, days, 0))', '!(!(selfsign)) || !(!X509_set_issuer_name(ret, X509_get_subject_name(x509)))', '!(selfsign) || !(!X509_set_issuer_name(ret, subject))', '!(BN_to_ASN1_INTEGER(serial, X509_get_serialNumber(ret)) == NULL)', '!((ret = X509_new_ex(app_get0_libctx(), app_get0_propq())) == NULL)', '!(preserve) || !(subject == NULL)', '!(j < 0)', '!(push != NULL) || !(!X509_NAME_add_entry(subject, push, -1, 0))', '!(!(strcmp(cv->value, "optional") == 0) && !(strcmp(cv->value, "supplied") == 0) && !(strcmp(cv->value, "match") == 0))', '!(j < 0)', '!(j >= 0) || !(ASN1_STRING_cmp(str, str2) != 0)', '!((j < 0) && (last2 == -1))', '!(i = 0; i < sk_CONF_VALUE_num(policy); i++) || !(;;) || !(strcmp(cv->value, "match") == 0) || !(tne == NULL)', '!(i = 0; i < sk_CONF_VALUE_num(policy); i++) || !(;;) || !(strcmp(cv->value, "supplied") == 0) || !(tne == NULL)', '!(i = 0; i < sk_CONF_VALUE_num(policy); i++) || !(;;) || !(j < 0) || !(last != -1)', '!(i = 0; i < sk_CONF_VALUE_num(policy); i++) || !((j = OBJ_txt2nid(cv->name)) == NID_undef)', '!(CAname == NULL)', '!((subject = X509_NAME_new()) == NULL)', '!(i = 0; i < X509_NAME_entry_count(name); i++) || !(str->type != V_ASN1_BMPSTRING && str->type != V_ASN1_UTF8STRING)', '!(i = 0; i < X509_NAME_entry_count(name); i++) || !(nid == NID_pkcs9_emailAddress && str->type != V_ASN1_IA5STRING)', '!(subj) || !(!n)']

